// The concept graph of the Study Guide (study/concepts.html, generated by
// scripts/build_study_guide.py). The page holds the data inline and a block of
// text for each concept; this script draws the graph and shows one block.
//
// Layout: a spring layout, computed once from a fixed seed, so every visit
// sees the same picture. Focus: the focused concept at the center, the
// concepts linked to it on a ring in the directions the layout gives them,
// and every other concept in the outer annulus at its direction from the
// focus, at a radius growing like tanh of its layout distance, shrinking
// toward the rim as in a Poincaré disk.
(function () {
  'use strict';
  var dataEl = document.getElementById('concept-data');
  var view = document.querySelector('.concept-view');
  var list = document.querySelector('.concept-list');
  var svg = document.getElementById('concept-svg');
  if (!dataEl || !view || !list || !svg) return;

  var data = JSON.parse(dataEl.textContent);
  var concepts = data.concepts;           // [term, id, track, essay]
  var N = concepts.length;
  var NS = 'http://www.w3.org/2000/svg';
  var R = 300, RING = 118, OUTER = 178;    // disk, ring of neighbours, inner edge of the rest
  var SIZE = { focus: 12, near: 7, overview: 3.4 };
  var SPREAD = 0.85;                       // how far outer angles move toward even spacing

  var byId = {};
  var nbrs = [];
  for (var i = 0; i < N; i++) { byId[concepts[i][1]] = i; nbrs.push([]); }
  data.links.forEach(function (l) { nbrs[l[0]].push(l[1]); nbrs[l[1]].push(l[0]); });

  // ------------------------------------------------------------ layout

  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  function springLayout() {
    var rand = mulberry32(20261113);
    var T = data.tracks.length, x = new Float64Array(N), y = new Float64Array(N);
    var spread = Math.sqrt(N) * 0.9;
    // Start each track in its own sector and each essay in a clump within it.
    var essaysOf = {};
    concepts.forEach(function (c) { (essaysOf[c[2]] = essaysOf[c[2]] || []).indexOf(c[3]) < 0 && essaysOf[c[2]].push(c[3]); });
    for (var i = 0; i < N; i++) {
      var t = concepts[i][2], es = essaysOf[t], e = es.indexOf(concepts[i][3]);
      var a = 2 * Math.PI * t / T, b = a + 2 * Math.PI * (e - (es.length - 1) / 2) / (T * Math.max(es.length, 2));
      x[i] = spread * (0.6 * Math.cos(a) + 0.35 * Math.cos(b)) + (rand() - 0.5) * 2;
      y[i] = spread * (0.6 * Math.sin(a) + 0.35 * Math.sin(b)) + (rand() - 0.5) * 2;
    }
    var dx = new Float64Array(N), dy = new Float64Array(N);
    var steps = 420, temp = spread * 0.25;
    for (var s = 0; s < steps; s++) {
      dx.fill(0); dy.fill(0);
      for (var p = 0; p < N; p++) {
        for (var q = p + 1; q < N; q++) {
          var ex = x[p] - x[q], ey = y[p] - y[q], d2 = ex * ex + ey * ey + 0.01;
          var f = 1 / d2;                          // repulsion k^2/d, k = 1
          dx[p] += ex * f; dy[p] += ey * f; dx[q] -= ex * f; dy[q] -= ey * f;
        }
      }
      data.links.forEach(function (l) {
        var a = l[0], b = l[1], ex = x[a] - x[b], ey = y[a] - y[b];
        var d = Math.sqrt(ex * ex + ey * ey) + 1e-9, f = d * (l[2] ? 0.35 : 1); // attraction d^2/k
        dx[a] -= ex * f; dy[a] -= ey * f; dx[b] += ex * f; dy[b] += ey * f;
      });
      for (var g = 0; g < N; g++) {                // gravity keeps the parts together
        dx[g] -= 0.04 * x[g]; dy[g] -= 0.04 * y[g];
        var m = Math.sqrt(dx[g] * dx[g] + dy[g] * dy[g]) + 1e-9, step = Math.min(m, temp);
        x[g] += dx[g] / m * step; y[g] += dy[g] / m * step;
      }
      temp = Math.max(spread * 0.25 * (1 - s / steps), 0.01);
    }
    return { x: x, y: y };
  }

  var L = springLayout();

  // ------------------------------------------------------------ targets

  function overviewTargets() {
    var x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity, i;
    for (i = 0; i < N; i++) {
      x0 = Math.min(x0, L.x[i]); x1 = Math.max(x1, L.x[i]);
      y0 = Math.min(y0, L.y[i]); y1 = Math.max(y1, L.y[i]);
    }
    var cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    var far = 0;
    for (i = 0; i < N; i++) far = Math.max(far, Math.abs(L.x[i] - cx), Math.abs(L.y[i] - cy));
    var k = (R + 24) / far, out = [];
    for (i = 0; i < N; i++) out.push({ x: (L.x[i] - cx) * k, y: (L.y[i] - cy) * k, r: SIZE.overview });
    return out;
  }

  // Angles on the ring, in the layout's order, at least `gap` apart.
  function spreadAngles(angles, gap) {
    var k = angles.length, order = angles.map(function (a, i) { return i; });
    order.sort(function (a, b) { return angles[a] - angles[b]; });
    var th = order.map(function (i) { return angles[i]; });
    if (k * gap >= 2 * Math.PI) {
      var mean = 0;
      for (var j = 0; j < k; j++) mean += th[j] - 2 * Math.PI * j / k;
      mean /= k;
      th = th.map(function (_, j) { return mean + 2 * Math.PI * j / k; });
    } else {
      for (var it = 0; it < 200; it++) {
        var moved = false;
        for (var j2 = 0; j2 < k && k > 1; j2++) {
          var n = (j2 + 1) % k, next = th[n] + (n === 0 ? 2 * Math.PI : 0), d = next - th[j2];
          if (d < gap - 1e-6) {
            var push = (gap - d) / 2;
            th[j2] -= push; th[n] += push; moved = true;
          }
        }
        if (!moved) break;
      }
    }
    var out = new Array(k);
    order.forEach(function (i, j) { out[i] = th[j]; });
    return out;
  }

  function focusTargets(f) {
    var out = new Array(N), near = nbrs[f], isNear = {};
    near.forEach(function (j) { isNear[j] = true; });
    out[f] = { x: 0, y: 0, r: SIZE.focus };
    var angles = near.map(function (j) { return Math.atan2(L.y[j] - L.y[f], L.x[j] - L.x[f]); });
    angles = spreadAngles(angles, Math.min(2 * Math.PI / Math.max(near.length, 1), 0.62));
    near.forEach(function (j, n) {
      out[j] = { x: RING * Math.cos(angles[n]), y: RING * Math.sin(angles[n]), r: SIZE.near };
    });
    var dist = [], i;
    for (i = 0; i < N; i++) if (i !== f && !isNear[i]) dist.push(Math.hypot(L.x[i] - L.x[f], L.y[i] - L.y[f]));
    dist.sort(function (a, b) { return a - b; });
    var scale = (dist[dist.length >> 1] || 1) / 0.55;   // the median concept lands mid-annulus
    // From a concept at the edge of the layout every other one lies to one
    // side. Their angles are pulled toward even spacing, in the same order,
    // so that the annulus fills.
    var rest = [];
    for (i = 0; i < N; i++) {
      if (i === f || isNear[i]) continue;
      rest.push({ i: i, a: Math.atan2(L.y[i] - L.y[f], L.x[i] - L.x[f]) });
    }
    rest.sort(function (p, q) { return p.a - q.a; });
    var n = rest.length, gap = 0, after = 0, k;
    for (k = 0; k < n; k++) {
      var next = k + 1 < n ? rest[k + 1].a : rest[0].a + 2 * Math.PI;
      if (next - rest[k].a > gap) { gap = next - rest[k].a; after = (k + 1) % n; }
    }
    var start = rest.length ? rest[after].a - gap / 2 : 0;
    for (k = 0; k < n; k++) {
      var item = rest[(after + k) % n], a = item.a;
      while (a < start) a += 2 * Math.PI;
      var even = start + 2 * Math.PI * (k + 0.5) / n;
      item.a = a + SPREAD * (even - a);
    }
    rest.forEach(function (item) {
      var j = item.i, d = Math.hypot(L.x[j] - L.x[f], L.y[j] - L.y[f]);
      var r = OUTER + (R - OUTER) * Math.tanh(d / scale), u = r / R;
      out[j] = { x: Math.cos(item.a) * r, y: Math.sin(item.a) * r,
                 r: 1.3 + 3.2 * (1 - u * u) / (1 - (OUTER / R) * (OUTER / R)) };
    });
    return out;
  }

  // ------------------------------------------------------------ drawing

  function el(name, attrs, parent) {
    var e = document.createElementNS(NS, name);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }

  var gEdges = el('g', { 'class': 'edges' }, svg);
  var gNodes = el('g', { 'class': 'nodes' }, svg);
  var gLabels = el('g', { 'class': 'labels' }, svg);
  var gHover = el('g', { 'class': 'hover' }, svg);
  var lines = data.links.map(function (l) {
    return el('line', { 'class': l[2] ? 'chain' : '' }, gEdges);
  });
  var dots = concepts.map(function (c) {
    return el('circle', { 'class': 'node t' + (c[2] + 1) }, gNodes);
  });

  var pos = overviewTargets();
  var focused = -1, anim = null;

  function draw(p) {
    for (var i = 0; i < N; i++) {
      dots[i].setAttribute('cx', p[i].x.toFixed(1));
      dots[i].setAttribute('cy', p[i].y.toFixed(1));
      dots[i].setAttribute('r', p[i].r.toFixed(2));
    }
    data.links.forEach(function (l, k) {
      var a = p[l[0]], b = p[l[1]];
      lines[k].setAttribute('x1', a.x.toFixed(1)); lines[k].setAttribute('y1', a.y.toFixed(1));
      lines[k].setAttribute('x2', b.x.toFixed(1)); lines[k].setAttribute('y2', b.y.toFixed(1));
    });
  }

  function ease(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }

  function moveTo(target, instant, done) {
    if (anim) cancelAnimationFrame(anim);
    var from = pos.map(function (p) { return { x: p.x, y: p.y, r: p.r }; });
    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (instant || reduce) { pos = target; draw(pos); done(); return; }
    var start = null, ms = 700;
    function frame(now) {
      if (start === null) start = now;
      var t = Math.min((now - start) / ms, 1), e = ease(t);
      pos = from.map(function (a, i) {
        var b = target[i];
        return { x: a.x + (b.x - a.x) * e, y: a.y + (b.y - a.y) * e, r: a.r + (b.r - a.r) * e };
      });
      draw(pos);
      if (t < 1) anim = requestAnimationFrame(frame);
      else { anim = null; pos = target; done(); }
    }
    anim = requestAnimationFrame(frame);
  }

  // ------------------------------------------------------------ labels

  function wrap(text, width, maxRows) {
    var words = text.split(' '), rows = [''];
    words.forEach(function (w) {
      var row = rows[rows.length - 1];
      if (row && (row + ' ' + w).length > width) rows.push(w);
      else rows[rows.length - 1] = row ? row + ' ' + w : w;
    });
    maxRows = maxRows || 2;
    if (rows.length > maxRows) rows = rows.slice(0, maxRows - 1).concat([rows.slice(maxRows - 1).join(' ')]);
    var last = rows.length - 1;
    if (rows[last].length > width + 2) rows[last] = rows[last].slice(0, width) + '…';
    return rows;
  }

  function textBlock(parent, rows, x, y, anchor, cls, lineHeight) {
    var t = el('text', { x: x, y: y, 'text-anchor': anchor, 'class': cls }, parent);
    rows.forEach(function (row, n) {
      var s = el('tspan', { x: x, dy: n ? lineHeight : 0 }, t);
      s.textContent = row;
    });
    return t;
  }

  // Each side of the ring stacks its labels so that none overlap.
  function placeSide(items) {
    items.sort(function (a, b) { return a.want - b.want; });
    var gap = 3;
    for (var i = 1; i < items.length; i++) {
      var prev = items[i - 1], min = prev.y + prev.h + gap;
      items[i].y = Math.max(items[i].want, min);
    }
    // Pull the stack back up if it ran off the bottom.
    var bottom = half - 4;
    for (var j = items.length - 1; j >= 0; j--) {
      var limit = j === items.length - 1 ? bottom - items[j].h : items[j + 1].y - gap - items[j].h;
      if (items[j].y > limit) items[j].y = limit;
    }
  }

  function drawLabels() {
    while (gLabels.firstChild) gLabels.removeChild(gLabels.firstChild);
    if (focused < 0) return;
    var LH = 14 * fs;
    var sides = { left: [], right: [] };
    nbrs[focused].forEach(function (j) {
      var p = pos[j], right = p.x >= -0.5;
      var room = half - Math.abs(p.x) - SIZE.near - 20;     // to the edge of the view
      var chars = Math.max(8, Math.min(Math.round(24 / fs), Math.floor(room / (6.2 * fs))));
      var rows = wrap(concepts[j][0], chars, fs > 1.2 ? 3 : 2), h = rows.length * LH;
      sides[right ? 'right' : 'left'].push({ j: j, rows: rows, h: h, want: p.y - h / 2 + 4 * fs, side: right });
    });
    ['left', 'right'].forEach(function (side) {
      var items = sides[side];
      items.forEach(function (it) { it.y = it.want; });
      placeSide(items);
      items.forEach(function (it) { placeLabel(it, LH); });
    });
    focusLabel();
  }

  function nodeBox(j) {
    var p = pos[j];
    return { x: p.x - p.r - 1, y: p.y - p.r - 1, width: 2 * p.r + 2, height: 2 * p.r + 2 };
  }

  // A neighbour's label at its stacked place; if it covers another neighbour,
  // the first of a few nearby variants that covers nothing.
  function placeLabel(it, LH) {
    var p = pos[it.j], dir = it.side ? 1 : -1;
    var others = nbrs[focused].filter(function (j) { return j !== it.j; }).map(nodeBox);
    var placed = Array.prototype.map.call(gLabels.querySelectorAll('text'), function (t) { return t.getBBox(); });
    var one = [concepts[it.j][0]];
    var variants = [[it.rows, 0], [one, 0]], step = SIZE.near * 2 + 3;
    [1, -1, 2, -2].forEach(function (k) { variants.push([it.rows, k * step], [one, k * step]); });
    var best = null;
    variants.some(function (v) {
      var rows = v[0], y = it.y + v[1], h = rows.length * LH;
      var g = el('g', {}, gLabels);
      var lx = p.x + dir * (SIZE.near + 5), mid = y + h / 2 - 4 * fs;
      if (Math.abs(mid - p.y) > 4) {
        lx = p.x + dir * (SIZE.near + 16);
        el('path', { 'class': 'leader', d: 'M' + (p.x + dir * SIZE.near).toFixed(1) + ' ' + p.y.toFixed(1) +
          ' L' + (lx - dir * 3).toFixed(1) + ' ' + (mid + 0.5).toFixed(1) }, g);
      }
      var t = textBlock(g, rows, lx.toFixed(1), (y + 10 * fs).toFixed(1), it.side ? 'start' : 'end', 'label near-label', LH);
      var box = t.getBBox();
      var hits = others.concat(placed).filter(function (b) { return overlaps(box, b); }).length;
      if (box.x < -half || box.x + box.width > half) hits += 1;
      if (!best || hits < best.hits) {
        if (best) gLabels.removeChild(best.g);
        best = { g: g, hits: hits };
      } else {
        gLabels.removeChild(g);
      }
      return hits === 0;
    });
  }

  // The focused concept's label goes below or above it, wherever it covers
  // no neighbour and no neighbour's label.
  function overlaps(a, b) {
    return !(a.x + a.width <= b.x || b.x + b.width <= a.x || a.y + a.height <= b.y || b.y + b.height <= a.y);
  }
  function focusLabel() {
    var taken = Array.prototype.map.call(gLabels.querySelectorAll('text'), function (t) { return t.getBBox(); });
    nbrs[focused].forEach(function (j) {
      var p = pos[j];
      taken.push({ x: p.x - p.r - 2, y: p.y - p.r - 2, width: 2 * p.r + 4, height: 2 * p.r + 4 });
    });
    var term = concepts[focused][0], best = null;
    [[22, 2], [15, 3]].some(function (fit) {
      var rows = wrap(term, Math.round(fit[0] / fs), fit[1] + (fs > 1.2 ? 1 : 0)), lh = 17 * fs, h = rows.length * lh;
      return [SIZE.focus + 6 + 12 * fs, -SIZE.focus - h + 6 * fs].some(function (y) {
        var t = textBlock(gLabels, rows, 0, y, 'middle', 'label focus-label', lh), box = t.getBBox();
        var hits = taken.filter(function (b) { return overlaps(box, b); }).length;
        if (!best || hits < best.hits) {
          if (best) gLabels.removeChild(best.t);
          best = { t: t, hits: hits };
        } else {
          gLabels.removeChild(t);
        }
        return hits === 0;
      });
    });
  }

  // ------------------------------------------------------------ size
  //
  // On a narrow screen the view crops to the disk, and labels grow so that
  // they stay readable at the size the graph is drawn.

  var fs = 1, half = 340;
  function fitToWidth() {
    var w = svg.getBoundingClientRect().width || 680;
    var narrow = w < 520, box = narrow ? 608 : 680;
    RING = narrow ? 128 : 118;
    OUTER = narrow ? 188 : 178;
    half = box / 2;
    svg.setAttribute('viewBox', [-half, -half, box, box].join(' '));
    fs = Math.min(Math.max(10 / (13 * w / box), 1), 1.9);
    svg.style.setProperty('--fs', fs.toFixed(3));
  }

  // ------------------------------------------------------------ state

  function markFocus() {
    var near = {};
    if (focused >= 0) nbrs[focused].forEach(function (j) { near[j] = true; });
    svg.classList.toggle('focused', focused >= 0);
    dots.forEach(function (d, i) {
      d.classList.toggle('is-focus', i === focused);
      d.classList.toggle('is-near', !!near[i]);
    });
    data.links.forEach(function (l, k) {
      var touch = l[0] === focused || l[1] === focused;
      var among = near[l[0]] && near[l[1]];
      lines[k].classList.toggle('touch', touch);
      lines[k].classList.toggle('among', !!among);
    });
    var cur = list.querySelector('.concept.current');
    if (cur) cur.classList.remove('current');
    hint.hidden = focused >= 0;
    if (focused >= 0) {
      var block = document.getElementById(concepts[focused][1]);
      if (block) block.classList.add('current');
    }
  }

  function setHash(id, push) {
    var url = location.pathname + location.search + (id ? '#' + id : '');
    if (push) history.pushState(null, '', url); else history.replaceState(null, '', url);
  }

  function focusOn(i, opts) {
    opts = opts || {};
    if (i === focused && !opts.force) return;
    focused = i;
    hideHover();
    while (gLabels.firstChild) gLabels.removeChild(gLabels.firstChild);
    markFocus();
    if (opts.push !== undefined) setHash(i >= 0 ? concepts[i][1] : '', opts.push);
    moveTo(i >= 0 ? focusTargets(i) : overviewTargets(), opts.instant, drawLabels);
  }

  function fromHash() {
    var id = decodeURIComponent(location.hash.slice(1));
    return id in byId ? byId[id] : -1;
  }

  // ------------------------------------------------------------ hover and click

  function svgPoint(evt) {
    var m = svg.getScreenCTM();
    if (!m) return null;
    var p = svg.createSVGPoint();
    p.x = evt.clientX; p.y = evt.clientY;
    return p.matrixTransform(m.inverse());
  }

  function nearest(pt) {
    var best = -1, bestD = Infinity;
    for (var i = 0; i < N; i++) {
      var d = Math.hypot(pos[i].x - pt.x, pos[i].y - pt.y), reach = Math.max(pos[i].r + 3, 8);
      if (d < reach && d - pos[i].r < bestD) { best = i; bestD = d - pos[i].r; }
    }
    return best;
  }

  var hovered = -1;
  function hideHover() {
    hovered = -1;
    while (gHover.firstChild) gHover.removeChild(gHover.firstChild);
    svg.style.cursor = '';
  }
  function showHover(i) {
    if (i === hovered) return;
    hideHover();
    if (i < 0) return;
    hovered = i;
    svg.style.cursor = 'pointer';
    var p = pos[i];
    el('circle', { 'class': 'hover-ring', cx: p.x, cy: p.y, r: p.r + 3 }, gHover);
    var right = p.x < R * 0.35;
    var x = p.x + (right ? 1 : -1) * (p.r + 6);
    var t = textBlock(gHover, [concepts[i][0]], x.toFixed(1), (p.y - 4 * fs).toFixed(1), right ? 'start' : 'end', 'label hover-label', 14 * fs);
    var s = el('tspan', { x: x.toFixed(1), dy: 14 * fs, 'class': 'hover-essay' }, t);
    s.textContent = data.essays[concepts[i][3]];
  }

  svg.addEventListener('pointermove', function (evt) {
    if (anim) return;
    var pt = svgPoint(evt);
    if (pt) showHover(nearest(pt));
  });
  svg.addEventListener('pointerleave', hideHover);
  svg.addEventListener('click', function (evt) {
    var pt = svgPoint(evt);
    if (!pt) return;
    var i = nearest(pt);
    if (i >= 0) focusOn(i, { push: true });
  });

  // ------------------------------------------------------------ the page around it

  var panel = view.querySelector('.concept-panel');
  var hint = panel.querySelector('.concept-hint');
  panel.appendChild(list);
  list.classList.add('js');
  view.hidden = false;

  list.addEventListener('click', function (evt) {
    var a = evt.target.closest && evt.target.closest('a[href^="#concept-"]');
    if (!a) return;
    var id = a.getAttribute('href').slice(1);
    if (id in byId) { evt.preventDefault(); focusOn(byId[id], { push: true }); }
  });
  window.addEventListener('popstate', function () { focusOn(fromHash(), {}); });
  window.addEventListener('hashchange', function () { focusOn(fromHash(), {}); });

  var search = document.getElementById('concept-search');
  var datalist = document.getElementById('concept-names');
  concepts.forEach(function (c) {
    var o = document.createElement('option');
    o.value = c[0];
    datalist.appendChild(o);
  });
  function findConcept(q) {
    q = q.trim().toLowerCase();
    if (!q) return -1;
    var i, starts = -1, has = -1;
    for (i = 0; i < N; i++) {
      var t = concepts[i][0].toLowerCase();
      if (t === q) return i;
      if (starts < 0 && t.indexOf(q) === 0) starts = i;
      if (has < 0 && t.indexOf(q) >= 0) has = i;
    }
    return starts >= 0 ? starts : has;
  }
  function searchGo() {
    var i = findConcept(search.value);
    search.classList.toggle('no-match', search.value.trim() !== '' && i < 0);
    if (i >= 0) focusOn(i, { push: true });
  }
  search.addEventListener('change', searchGo);
  search.addEventListener('keydown', function (evt) { if (evt.key === 'Enter') { evt.preventDefault(); searchGo(); } });
  search.addEventListener('input', function () {
    search.classList.remove('no-match');
    // A name picked from the list of suggestions arrives as an exact match.
    if (concepts.some(function (c) { return c[0] === search.value; })) searchGo();
  });

  document.getElementById('concept-overview').addEventListener('click', function () {
    search.value = '';
    focusOn(-1, { push: true });
  });

  // Highlighting a track in the legend: color is not the only cue to a track.
  var legend = view.querySelector('.concept-legend'), sticky = -1;
  function highlight(t) {
    svg.classList.toggle('track-hl', t >= 0);
    dots.forEach(function (d, i) { d.classList.toggle('hl', concepts[i][2] === t); });
    legend.querySelectorAll('button').forEach(function (b) {
      b.classList.toggle('on', +b.dataset.track === t);
      b.setAttribute('aria-pressed', +b.dataset.track === sticky ? 'true' : 'false');
    });
  }
  legend.querySelectorAll('button').forEach(function (b) {
    var t = +b.dataset.track;
    b.addEventListener('mouseenter', function () { highlight(t); });
    b.addEventListener('mouseleave', function () { highlight(sticky); });
    b.addEventListener('focus', function () { highlight(t); });
    b.addEventListener('blur', function () { highlight(sticky); });
    b.addEventListener('click', function () { sticky = sticky === t ? -1 : t; highlight(sticky); });
  });

  fitToWidth();
  var resizeTimer = null;
  window.addEventListener('resize', function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      var before = fs;
      fitToWidth();
      if (fs !== before && !anim) drawLabels();
    }, 150);
  });

  draw(pos);
  var start = fromHash();
  if (start >= 0) {
    focusOn(start, { instant: true, force: true });
    view.scrollIntoView({ block: 'start' });
  } else {
    markFocus();
  }
})();
